<script lang="ts">
  import Button from './ui/Button.svelte';
  import { onDestroy } from 'svelte';
  import { RefreshCw, Download, Activity } from '@lucide/svelte';
  import Select from './ui/Select.svelte';
  import Switch from './ui/Switch.svelte';
  import {
    computeChoices, diagnosticCheckLabels, recentRuntimeErrors, redactDiagnosticText, redactDiagnosticValue, runOfflineDiagnostics, runtimeLogs, runtimeSnapshot,
    saveCompileDisabled, saveComputeDevice, savePerformance, unloadRuntimeModel,
    type DiagnosticReport, type LoadedModel, type RecentError, type RuntimeSnapshot,
  } from './runtime-diagnostics';
  import './studio-tools.css';
  let { ready, onrestart }: { ready:boolean; onrestart?:()=>Promise<void> } = $props();
  let opened=$state(false), snapshot=$state<RuntimeSnapshot>(), report=$state<DiagnosticReport>(), errors=$state<RecentError[]>([]), logs=$state<string[]>([]);
  let loading=$state(false),busy=$state(false),error=$state(''),message=$state(''),logMessage=$state('');
  let device=$state('auto'),family=$state('tts'),tier=$state('balanced'),compileDisabled=$state(false),unloading=$state<LoadedModel>();
  let deviceEdited=$state(false),performanceEdited=$state(false),compileEdited=$state(false),disposed=false;
  let readController:AbortController|undefined,actionController:AbortController|undefined;
  const familyNames:Record<string,string>={tts:'Synteza mowy',asr:'Rozpoznawanie mowy',translation:'Tłumaczenie',dictation:'Dyktowanie',diarisation:'Rozdzielanie mówców',llm:'Model językowy'};
  const tiers:Record<string,string>={fast:'Szybki',balanced:'Zrównoważony',quality:'Jakość',max:'Maksymalny'};
  const amount=(value?:number)=>typeof value==='number'&&Number.isFinite(value)?value.toLocaleString('pl-PL',{maximumFractionDigits:2}):'brak pomiaru';
  const partialErrors=$derived(snapshot?Object.entries(snapshot).filter(([,value])=>value&&typeof value==='object'&&'error' in value).map(([key,value])=>`${({memory:'Pamięć',models:'Modele',watermark:'Znak wodny',media:'Narzędzia multimedialne',compute:'Urządzenie',performance:'Wydajność',compile:'Kompilacja'} as Record<string,string>)[key]||key}: ${(value as {error:string}).error}`):[]);
  function applyDrafts(next:RuntimeSnapshot){
    if(!deviceEdited&&next.compute.data)device=next.compute.data.value;
    if(next.performance.data&&!performanceEdited){if(!next.performance.data.applicable_families.includes(family))family=next.performance.data.applicable_families[0]||'';tier=next.performance.data.effective[family]||next.performance.data.global;}
    if(!compileEdited&&next.compile.data)compileDisabled=next.compile.data.enabled;
  }
  async function refresh(signal?:AbortSignal){
    readController?.abort();const current=new AbortController();readController=current;const combined=signal?AbortSignal.any([signal,current.signal]):current.signal;loading=true;
    try{const next=await runtimeSnapshot(combined);combined.throwIfAborted();if(disposed)return;snapshot=next;applyDrafts(next);}
    finally{if(readController===current&&!disposed)loading=false;}
  }
  function fail(cause:unknown){if(!disposed&&(cause as Error).name!=='AbortError')error=redactDiagnosticText((cause as Error).message||cause);}
  async function work(fn:(signal:AbortSignal)=>Promise<void>){if(!ready||busy||loading||disposed)return;const current=new AbortController();actionController=current;busy=true;error='';message='';try{await fn(current.signal);}catch(cause){if(!current.signal.aborted)fail(cause);}finally{if(actionController===current&&!disposed)busy=false;}}
  async function diagnose(){await work(async signal=>{report=await runOfflineDiagnostics(signal);signal.throwIfAborted();message='Zakończono lokalne kontrole gotowości. Nie wykonano syntezy ani testu połączenia z internetem.';});}
  async function loadLogs(){await work(async signal=>{const [journal,tail]=await Promise.allSettled([recentRuntimeErrors(signal),runtimeLogs(signal)]);signal.throwIfAborted();logMessage='';if(journal.status==='fulfilled')errors=journal.value.errors;else logMessage+=`Dziennik błędów: ${redactDiagnosticText(journal.reason?.message)}. `;if(tail.status==='fulfilled'){logs=tail.value.lines;if(!tail.value.exists)logMessage+='Silnik nie ma jeszcze pliku logu.';}else logMessage+=`Log: ${redactDiagnosticText(tail.reason?.message)}.`;});}
  async function saveDevice(){if(!snapshot?.compute.data)return;await work(async signal=>{const next=await saveComputeDevice(device,snapshot!.compute.data!,signal);signal.throwIfAborted();snapshot={...snapshot!,compute:{data:next}};deviceEdited=false;device=next.value;message=next.restart_required?'Zapisano urządzenie. Zmiana wymaga ponownego uruchomienia silnika.':'Zapisano ustawienie urządzenia.';});}
  async function saveTier(){if(!snapshot?.performance.data)return;await work(async signal=>{const next=await savePerformance(tier,family,snapshot!.performance.data!,signal);signal.throwIfAborted();snapshot={...snapshot!,performance:{data:next}};performanceEdited=false;message='Zapisano preset wydajności dla wybranej rodziny silników.';});}
  async function saveCompilation(){await work(async signal=>{const next=await saveCompileDisabled(compileDisabled,signal);signal.throwIfAborted();snapshot={...snapshot!,compile:{data:next}};compileEdited=false;message='Zapisano tryb kompilacji. Zostanie użyty przy kolejnym załadowaniu modelu.';});}
  async function unload(){if(!unloading)return;await work(async signal=>{await unloadRuntimeModel(unloading!,signal);signal.throwIfAborted();unloading=undefined;await refresh(signal);message='Zwolniono wskazany model. Przy następnym użyciu silnik wczyta go ponownie.';});}
  function downloadReport(){if(!snapshot)return;const blob=new Blob([JSON.stringify(redactDiagnosticValue({snapshot,diagnostics:report,recentErrors:errors,logs}),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download='seventy-seven-labs-diagnostyka.json';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),30_000);}
  $effect(()=>{if(!ready||!opened)return;const current=new AbortController();void refresh(current.signal).catch(cause=>{if(!current.signal.aborted)fail(cause);});return()=>{current.abort();readController?.abort();actionController?.abort();loading=false;busy=false;};});
  onDestroy(()=>{disposed=true;readController?.abort();actionController?.abort();});
</script>

<details class="studio-tools runtime-diagnostics" bind:open={opened}>
  <summary>Diagnostyka i wydajność silnika</summary>
  <p class="page-footnote">Sprawdź pamięć, wczytane modele i lokalne zależności. Ustawienia są zapisywane wyłącznie przyciskiem w danej sekcji.</p>
  {#if !ready}<p class="tool-notice">Uruchom lokalny silnik, aby odczytać rzeczywiste dane.</p>{/if}{#if error}<p class="tool-error" role="alert">{error}</p>{/if}{#if message}<p class="tool-notice" role="status">{message}</p>{/if}
  <div class="tool-actions"><Button variant="outline" disabled={!ready||busy||loading} onclick={()=>work(refresh)}><RefreshCw size={15}/>{loading?'Odczytywanie…':'Odśwież stan'}</Button><Button variant="outline" disabled={!ready||busy||loading} onclick={diagnose}><Activity size={15}/>Sprawdź gotowość lokalnie</Button><Button variant="outline" disabled={!snapshot||busy||loading} onclick={downloadReport}><Download size={15}/>Pobierz raport JSON</Button></div>
  {#if partialErrors.length}<p class="tool-error" role="alert">{partialErrors.join('\n')}</p>{/if}
  {#if snapshot}<p class="page-footnote">Ostatni pełny odczyt: {new Date(snapshot.capturedAt).toLocaleString('pl-PL')}.</p>
    {#if snapshot.memory.data}<div class="tool-card"><h3>Pamięć i obciążenie</h3><dl class="diagnostic-values"><dt>Wolna / łączna RAM</dt><dd>{amount(Math.max(0,snapshot.memory.data.total_ram-snapshot.memory.data.ram))} / {amount(snapshot.memory.data.total_ram)} GiB</dd><dt>CPU</dt><dd>{amount(snapshot.memory.data.cpu)}% · {snapshot.memory.data.cpu_model||'Brak nazwy procesora'}</dd><dt>GPU</dt><dd>{snapshot.memory.data.gpu_name||'Nie wykryto nazwy GPU'}</dd><dt>Wolna / łączna VRAM</dt><dd>{snapshot.memory.data.total_vram>0?`${amount(Math.max(0,snapshot.memory.data.total_vram-snapshot.memory.data.vram))} / ${amount(snapshot.memory.data.total_vram)} GiB`:'Brak wiarygodnego pomiaru całkowitej VRAM'}</dd></dl></div>{/if}
    {#if snapshot.models.data}<div class="tool-card"><h3>Modele w pamięci</h3>{#if !snapshot.models.data.models.length}<p class="page-footnote">Silnik nie zgłasza wczytanych modeli.</p>{/if}<div class="tool-list">{#each snapshot.models.data.models as model (model.id)}<article><div class="tool-row-main"><strong>{model.name}</strong><small>{model.device||'Urządzenie niezgłoszone'} · {model.vram_mb?`${amount(model.vram_mb)} MB VRAM`:'Zajęcie VRAM niezmierzone'}{model.checkpoint?` · ${model.checkpoint}`:''}</small>{#if model.note}<small>{model.note}</small>{/if}</div><Button variant="outline" disabled={!ready||busy||loading||!model.unloadable} onclick={()=>unloading=model}>Zwolnij z pamięci</Button></article>{/each}</div>{#if unloading}<div class="tool-confirm">Zwolnić „{unloading.name}” z pamięci? Następne użycie wymaga ponownego wczytania. Zakończ aktywne zadania przed tą operacją.<Button variant="outline" disabled={!ready||busy||loading} onclick={unload}>Potwierdź zwolnienie modelu</Button><Button variant="ghost" disabled={busy} onclick={()=>unloading=undefined}>Zachowaj model</Button></div>{/if}</div>{/if}
    {#if snapshot.compute.data}<div class="tool-card"><h3>Urządzenie obliczeń</h3><p class="page-footnote">Używane: {snapshot.compute.data.effective_family}. Automatyczny wybór: {snapshot.compute.data.auto_family}.{snapshot.compute.data.env_pinned?' Urządzenie przypięto w konfiguracji uruchomienia.':''}{snapshot.compute.data.override_ignored?' Żądane urządzenie jest niedostępne; silnik zastosował wybór automatyczny.':''}</p><Select label="Urządzenie po restarcie" value={device} onchange={value=>{device=value;deviceEdited=true;}} options={computeChoices(snapshot.compute.data).map(value=>({value,label:value==='auto'?'Automatycznie':value.toUpperCase()}))} disabled={!ready||busy||loading||snapshot.compute.data.env_pinned}/><Button variant="outline" disabled={!ready||busy||loading||!deviceEdited||snapshot.compute.data.env_pinned} onclick={saveDevice}>Zapisz urządzenie</Button>{#if snapshot.compute.data.restart_required}<p class="tool-notice">Zmiana wymaga ponownego uruchomienia silnika.</p>{#if onrestart}<Button variant="outline" disabled={!ready||busy||loading} onclick={()=>work(async signal=>{await onrestart!();signal.throwIfAborted();await refresh(signal);})}>Uruchom ponownie silnik</Button>{/if}{/if}</div>{/if}
    {#if snapshot.performance.data}<div class="tool-card"><h3>Preset wydajności</h3><p class="page-footnote">Preset może wybrać inny zainstalowany model dla tej rodziny. Zapis nie rozpoczyna pobierania brakujących wag.</p><div class="tool-columns"><Select label="Rodzina silników" value={family} onchange={value=>{family=value;tier=snapshot!.performance.data!.effective[value]||snapshot!.performance.data!.global;performanceEdited=true;}} options={snapshot.performance.data.applicable_families.map(value=>({value,label:familyNames[value]||value}))} disabled={!ready||busy||loading}/><Select label="Szybkość i jakość" value={tier} onchange={value=>{tier=value;performanceEdited=true;}} options={snapshot.performance.data.tiers.map(value=>({value,label:tiers[value]||value}))} disabled={!ready||busy||loading||!family}/></div>{#if snapshot.performance.data.selections?.[family]}<p class="page-footnote">Wybrany silnik/model: {snapshot.performance.data.selections[family].engine} / {snapshot.performance.data.selections[family].model||'Nie zgłoszono modelu'}.</p>{/if}<Button variant="outline" disabled={!ready||busy||loading||!performanceEdited||!family} onclick={saveTier}>Zapisz preset tej rodziny</Button></div>{/if}
    {#if snapshot.compile.data}<div class="tool-card"><h3>Kompilacja modelu</h3><div class="diagnostic-switch"><span>Wyłącz torch.compile</span><Switch label="Wyłącz torch.compile" checked={compileDisabled} onchange={value=>{compileDisabled=value;compileEdited=true;}} disabled={!ready||busy||loading}/></div><p class="page-footnote">Zmiana obowiązuje przy kolejnym załadowaniu modelu. Tryb bez kompilacji może zmienić zużycie pamięci i czas generowania.</p><Button variant="outline" disabled={!ready||busy||loading||!compileEdited} onclick={saveCompilation}>Zapisz tryb kompilacji</Button></div>{/if}
    {#if snapshot.media.data}<div class="tool-card"><h3>Narzędzia multimedialne</h3><p>{snapshot.media.data.ready?'FFmpeg i FFprobe są dostępne.':'Zależności multimedialne wymagają przygotowania.'}</p><dl class="diagnostic-values">{#each Object.entries(snapshot.media.data.tools) as [name,tool]}<dt>{name}</dt><dd>{tool.ok?'Dostępne':'Niedostępne'}{tool.version?` · ${tool.version}`:''}{tool.origin?` · ${tool.origin}`:''}</dd>{/each}</dl></div>{/if}
    {#if snapshot.watermark.data}<div class="tool-card"><h3>Oznaczanie wygenerowanych nagrań</h3><p class="page-footnote">AudioSeal: {snapshot.watermark.data.audioseal_available?'dostępny':'niedostępny'}. Niewidoczne oznaczanie: {snapshot.watermark.data.invisible_enabled?'włączone':'wyłączone'}. Widoczne oznaczenie audio: {snapshot.watermark.data.visible_audio_enabled?'włączone':'wyłączone'}. Widoczne oznaczenie wideo: {snapshot.watermark.data.visible_video_enabled?'włączone':'wyłączone'}.</p></div>{/if}
  {/if}
  {#if report}<div class="tool-card"><h3>Kontrole lokalnej gotowości</h3><p>{report.summary.passed} poprawnych · {report.summary.warnings} ostrzeżeń · {report.summary.failures} błędów.</p><p class="page-footnote">Kontrole środowiska nie zastępują próby syntezy.</p><div class="tool-list">{#each report.checks as check}<article><div class="tool-row-main"><strong>{diagnosticCheckLabels[check.id]||check.label} · {({ok:'Poprawnie',warn:'Uwaga',fail:'Błąd'} as Record<string,string>)[check.status]||check.status}</strong><small>{check.detail}</small>{#if check.hint}<small>{check.hint}</small>{/if}</div></article>{/each}</div></div>{/if}
  <div class="tool-card"><h3>Ostatnie błędy i log silnika</h3><p class="page-footnote">Odczyt obejmuje dziennik silnika i ostatnie 100 linii jego logu. Znane wzorce poświadczeń i katalog domowy są ukrywane przed wyświetleniem i eksportem.</p><Button variant="outline" disabled={!ready||busy||loading} onclick={loadLogs}>Wczytaj błędy i końcówkę logu</Button>{#if logMessage}<p class="tool-notice">{logMessage}</p>{/if}{#each errors as item}<div class="diagnostic-error"><strong>{item.error_class||'Błąd silnika'}{item.count?` · wystąpienia: ${item.count}`:''}</strong><p>{item.message||item.route||'Szczegóły w logu silnika'}</p></div>{/each}{#if logs.length}<pre class="diagnostic-log">{logs.join('\n')}</pre>{/if}</div>
</details>

<style>.runtime-diagnostics{margin-top:28px}.runtime-diagnostics>summary{font-size:var(--ui-text-15);font-weight:550;cursor:pointer;line-height:1.8}.runtime-diagnostics h3{margin:0;font-size:var(--ui-text-14)}.diagnostic-values{display:grid;grid-template-columns:minmax(130px,.8fr) minmax(0,1.2fr);gap:12px;font-size:var(--ui-text-12);line-height:1.7}.diagnostic-values dt{color:var(--muted)}.diagnostic-values dd{margin:0;overflow-wrap:anywhere}.diagnostic-switch{display:flex;justify-content:space-between;gap:14px;align-items:center;font-size:var(--ui-text-13)}.diagnostic-log{max-height:360px;overflow:auto;background:var(--background);padding:14px;border:1px solid var(--border);border-radius:8px}.diagnostic-error{padding:10px;border-left:2px solid #ba5555;font-size:var(--ui-text-12);line-height:1.7}.diagnostic-error p{white-space:pre-wrap;overflow-wrap:anywhere;margin-bottom:0}@media(max-width:650px){.diagnostic-values{grid-template-columns:1fr;gap:7px}.diagnostic-values dd{margin-bottom:9px}}</style>
